code:
// ── 🎮 menu-juego · F5.3 · el menú de pausa ──────────────────────────────────────────────────────
//
//   game.menu.on()      instalar (viene puesto al ejecutar el snippet)
//   game.menu.off()     devolver el motor EXACTAMENTE como estaba
//   game.menu.abrir()   abrirlo a mano, sin pasar por Esc
//   game.menu.estado()  qué está puesto y en qué mapa
//
// ⛔ CERO LÍNEAS DE `app.js` (ley de oro). A `Esc` no se le toca el manejador: se le pone DELANTE un
// oyente en CAPTURA que decide, y `off()` lo quita con `removeEventListener`. Es el mismo camino que
// abrió `sesion-guardia`, y devuelve el motor byte a byte porque nunca llegó a tocarlo.
//
// LO QUE ESC HACE HOY (`app.js:3862-3872`) Y HAY QUE HEREDAR SIN REESCRIBIRLO: es una ESCALERA. Con
// el Mundo abierto va cerrando lo que haya encima —la nota que se está plantando, el panel de código,
// el de agentes, el editor de nota, el selector, la pantalla OSD—, después suelta el ratón, y solo al
// final cierra el Mundo.
//
// De esa escalera aquí se cambia UN escalón: el último. Sin menú, la última pulsación de Esc TIRA LA
// PARTIDA, que es lo contrario de lo que espera quien pulsa Esc en un juego. Ahora ese escalón abre
// el menú, y quien de verdad quiera irse lo dice en SALIR. Los escalones de arriba se dejan pasar
// intactos: no se reimplementan, se heredan — si mañana `app.js` añade uno, sigue funcionando.
//
// ⚠️ Y se abre al PRIMER Esc, no al segundo. El navegador suelta el puntero él solo al pulsar Esc
// (eso no se puede evitar desde JS), así que el escalón de «suelta el ratón» no se ve: lo que se veía
// era que hacía falta pulsar dos veces para que pasara algo. Un menú de pausa que pide dos Esc no es
// un menú de pausa.

const G = (window.game = window.game || {});
const M = (G.menu = G.menu || {});

M.VERSION = 'v1.3';

// El mapa de ahora mismo. Se lee en cada uso y no se guarda: con el relevo entre mapas de multi, un
// menú que recuerde el mapa de cuando se instaló invita al mapa equivocado.
M.mapa = function () {
  try { return G.mapName || 'default'; } catch (e) { return 'default'; }
};

// ── Las pantallas ────────────────────────────────────────────────────────────────────────────────
//
// El texto del botón ES su identidad (trim + mayúsculas), y el REGISTRO DE ACCIONES ES UNO SOLO para
// toda la página (`mc.osdAcciones`). O sea que dos menús que llamen «AJUSTES» a un botón se pisan el
// uno al otro, y gana el último que se cargue.
//
// ⚠️ NO ES HIPOTÉTICO, PASÓ AQUÍ: `mundo-autoarranque` carga `sesion-guardia` (que trae este menú) y
// DESPUÉS carga `miosd`, el menú del dueño, que registra `AJUSTES`, `VOLAR`, `FANTASMA`… Con los
// nombres a pelo, «AJUSTES» de la pausa abría las FÍSICAS de `miosd`, y `VOLAR` de `miosd` corría el
// de la pausa. Por eso TODOS los botones de aquí llevan `data-osd="pausa:…"`: `mcOsdEngancha` lee
// `dataset.osd || textContent` (`app.js:19534`), así que el texto sigue siendo lo que se lee en
// pantalla y la identidad pasa a ser una clave que no puede chocar con la de nadie.
//
// De propina, resuelve lo de siempre: un botón que pone «VOLAR: ON» y pasa a «VOLAR: OFF» perdería
// su acción al repintarse si se identificara por el texto.

// El andamio del OSD ya trae `.mc-osd-panel`, `.mc-osd-title` y `.mc-osd-btn` (`style.css:963-981`), y
// las medidas viven en variables (`--osd-boton`, `--osd-hueco`…) que `mcOsdMedidas` escribe DESDE EL
// `define`. Lo que este menú añade de su cosecha —la nota y la caja del enlace— se mide con esas
// mismas variables en un `style` de la propia etiqueta: así el tamaño lo sigue mandando `cfg` y no hay
// que tocar `style.css` para una pantalla.
M.NOTA = 'style="max-width:var(--osd-ancho); margin:0; text-align:center; color:#cfd8e6; ' +
  'font-size:calc(var(--osd-boton) * 0.7); line-height:1.5"';
M.ENLACE = 'style="width:var(--osd-ancho); box-sizing:border-box; padding:calc(var(--osd-boton)*0.5); ' +
  'font-size:calc(var(--osd-boton) * 0.7); color:#fff; background:rgba(8,11,18,.9); ' +
  'border:1px solid rgba(255,255,255,.28); border-radius:var(--osd-boton-radio)"';

// Un botón: la clave que manda, y el texto que se lee. Escribirlos siempre por aquí es lo que impide
// que se cuele uno sin `data-osd`, que es como volvería el choque con `miosd` sin que nada avise.
M.boton = function (clave, texto) {
  return '<button class="mc-osd-btn" data-osd="' + M.escapa(M.CLAVE + clave) + '">' + M.escapa(texto) + '</button>';
};

M.CLAVE = 'pausa:';

M.panel = function () {
  return '<div class="mc-osd-panel">' +
    '<div class="mc-osd-title">PAUSA</div>' +
    M.boton('continuar', 'CONTINUAR') +
    M.boton('multi', 'MULTIJUGADOR') +
    M.boton('ajustes', 'AJUSTES') +
    M.boton('mundos', 'MIS MUNDOS') +
    M.boton('salir', M.textoSalir()) +
    '</div>';
};

// ── 👥 MULTIJUGADOR ────────────────────────────────────────────────────────────────────────────
//
// Antes INVITAR colgaba de la pausa y era lo único que había del multijugador. Ahora cuelgan de aquí
// las DOS cosas que se pueden hacer con él, que es lo que pidió el dueño: entrar y traer a alguien.
//
// ⛔ El rótulo dice LO QUE VA A PASAR AL PULSAR, no el estado. «ACTIVAR» cuando estoy fuera,
// «DESACTIVAR» cuando estoy dentro; el estado se lee en la nota de arriba, que es donde se lee. Un
// botón que ponga «MULTIJUGADOR: ON» obliga a adivinar si eso es lo que hay o lo que hará.
M.panelMulti = function (aviso) {
  const dentro = M.multiPuesto();
  return '<div class="mc-osd-panel">' +
    '<div class="mc-osd-title">MULTIJUGADOR</div>' +
    '<p ' + M.NOTA + '>' + M.escapa(aviso || M.notaMulti()) + '</p>' +
    M.boton('multi-onoff', dentro ? 'DESACTIVAR MULTIJUGADOR' : 'ACTIVAR MULTIJUGADOR') +
    M.boton('invitar', 'INVITAR') +
    M.boton('volver', 'VOLVER') +
    '</div>';
};

// `game.multi` solo existe si `multi-verse` está cargado, y estar cargado no es estar dentro: `sal()`
// lo deja puesto y desconectado. Lo que manda es `estado().activo`.
M.multiPuesto = function () {
  try { return !!(G.multi && G.multi.estado && G.multi.estado().activo); } catch (e) { return false; }
};

// ⛔ «activo» NO es «conectado». `entra()` levanta la bandera ANTES de que exista el socket, y si el
// árbitro rechaza el apretón la baja `onclose` un rato después (multi-verse:1923) — que es justo lo
// que pasa cuando al árbitro le falta `VOXELFORGE_SECRETO_SESION` y no verifica ningún vale. Decir
// «Dentro» mientras la conexión vuela es prometer algo que todavía puede no ocurrir.
M.notaMulti = function () {
  let e = null;
  try { e = (G.multi && G.multi.estado) ? G.multi.estado() : null; } catch (er) {}
  if (!e || !e.activo) return 'Estás jugando a solas en «' + M.mapa() + '».';
  // Los cuatro nombres salen de `estado()` en multi-verse, que traduce `ws.readyState`.
  if (e.socket === 'conectando' || e.socket === 'sin socket') return 'Conectando con el servidor de multijugador…';
  if (e.socket !== 'abierto') return 'Se ha cortado la conexión con el servidor de multijugador.';
  const otros = e.otrosAhora || 0;
  return otros ? ('Dentro, y ahora mismo hay ' + otros + ' más.') : 'Dentro. Todavía no hay nadie más.';
};

// Qué pantalla se está viendo AHORA. `game.osd.abierta` dice «pausa» para TODAS las de este menú, así
// que no sirve para decidir un repintado tardío: el título sí. Sin esto, la vuelta de encender borra
// el enlace de INVITAR justo cuando lo estás copiando.
M.enPantalla = function (titulo) {
  try {
    const t = document.querySelector('#mc-osd .mc-osd-title');
    return !!t && t.textContent.trim() === titulo;
  } catch (e) { return false; }
};

// ⛔ LA MISMA LLAVE QUE `multi-verse` (su `LLAVE_VALE`, línea 61), y por eso está anotada en los dos
// sitios: es sessionStorage, o sea que el vale no sobrevive a cerrar la pestaña, que es lo que se
// quiere de una llave de la casa de otro. Si una de las dos cambia sola, encender deja de funcionar
// sin que nada falle — lo vigila `tests/test_menu_juego.js` §9.
M.LLAVE_VALE = 'vf_multi_vale:';

M.guardaVale = function (vale) {
  try { sessionStorage.setItem(M.LLAVE_VALE + M.mapa(), vale); return true; } catch (e) { return false; }
};

// Una sola petición para las dos cosas: el `enlace` es para el otro y el `vale` es para mí. Pedir dos
// veces daría dos vales distintos por el mismo motivo, y el segundo no serviría para nada.
M.pideVale = function () {
  return fetch('/api/invitaciones', {
    method: 'POST',
    credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ slug: M.mapa() }),
  }).then(function (r) {
    return r.json().catch(function () { return {}; })
      .then(function (d) { return { ok: r.ok, codigo: r.status, d: d || {} }; });
  });
};

// ⛔ AQUÍ ESTÁ (b): un jugador normal no tiene el secreto del árbitro y no debe tenerlo, pero SÍ
// puede pedirse un vale del mapa en el que ya escribe. Con el vale puesto, `entra()` no pregunta ni
// el secreto ni la dirección (multi-verse:2010), así que encender es un botón y no un cuestionario.
//
// `game.snippet('multi-verse')` acaba llamando a `entra()` él solo; si ya estaba cargado se llama a
// `entra()` y no se recarga el snippet, que montaría un segundo cliente sobre el mismo `mcUpdate`.
M.enciende = function () {
  if (M.multiPuesto()) return Promise.resolve('ya estabas dentro');
  return M.pideVale().then(function (r) {
    if (!r.ok) throw new Error(M.porQueNo(r.codigo, r.d));
    if (!r.d.vale) throw new Error('el servidor no ha devuelto vale');
    M.guardaVale(r.d.vale);
    if (G.multi && G.multi.entra) return G.multi.entra();
    return G.snippet('multi-verse');
  });
};

M.apaga = function () {
  try { if (G.multi && G.multi.sal) G.multi.sal(); } catch (e) {}
  return true;
};

// El botón no puede quedarse mudo mientras vuela la petición y el socket: encender pasa por el
// servidor y por el árbitro, y eso es medio segundo largo en el que un menú quieto parece roto.
M.conmutaMulti = function () {
  if (M.multiPuesto()) { M.apaga(); return Promise.resolve(G.osd.html(M.panelMulti())); }
  G.osd.html(M.panelMulti('Entrando…'));
  return M.enciende()
    .then(function () { if (M.enPantalla('MULTIJUGADOR')) G.osd.html(M.panelMulti()); })
    .catch(function (e) {
      if (M.enPantalla('MULTIJUGADOR')) G.osd.html(M.panelMulti('No se ha podido entrar: ' + (e && e.message)));
    });
};

M.panelInvita = function (enlace, escritura, error) {
  if (error) {
    return '<div class="mc-osd-panel">' +
      '<div class="mc-osd-title">INVITAR</div>' +
      '<p ' + M.NOTA + '>' + M.escapa(error) + '</p>' +
      M.boton('volver-multi', 'VOLVER') +
      '</div>';
  }
  // ⚠️ El enlace se ENSEÑA para copiarlo a mano, no se manda al portapapeles: `navigator.clipboard`
  // solo existe en contexto seguro, y esto arranca en LAN por `http://`. Un botón «Copiar» que no
  // copia y no lo dice es peor que no tenerlo (`docs/servidor-y-apis.md:103`).
  const nota = escritura === 'dueno'
    ? 'Podrá MIRAR, no construir: este mapa solo lo escribes tú.'
    : 'Podrá entrar y CONSTRUIR contigo.';
  return '<div class="mc-osd-panel">' +
    '<div class="mc-osd-title">INVITAR</div>' +
    '<p ' + M.NOTA + '>' + M.escapa(nota) + '</p>' +
    '<input ' + M.ENLACE + ' readonly value="' + M.escapa(enlace) + '">' +
    '<p ' + M.NOTA + '>Selecciónalo y cópialo.</p>' +
    '<p ' + M.NOTA + '>' + M.escapa(M.notaMulti()) + '</p>' +
    M.boton('volver-multi', 'VOLVER') +
    '</div>';
};

// ⚠️ `game.volar` es una FUNCIÓN-VALOR (`app.js:23139`): el getter devuelve una función con `valueOf`,
// así que `G.volar ? 'ON' : 'OFF'` da siempre 'ON' —un objeto siempre es cierto— y `G.volar(!G.volar)`
// apaga siempre, porque `!<función>` es siempre `false`. Se lee coaccionando (`+`) y se conmuta
// llamándola SIN argumentos, que es justo para lo que está escrita así.
M.volando = function () { return !!+G.volar; };

M.panelAjustes = function () {
  const volar = M.volando() ? 'ON' : 'OFF';
  const raton = Math.round((G.mouseSpeed || 1) * 100) / 100;
  return '<div class="mc-osd-panel">' +
    '<div class="mc-osd-title">AJUSTES</div>' +
    M.boton('volar', 'VOLAR: ' + volar) +
    M.boton('raton', 'RATÓN: ' + raton) +
    M.boton('pantalla', 'PANTALLA COMPLETA') +
    M.boton('volver', 'VOLVER') +
    '</div>';
};

M.escapa = function (s) {
  return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
  });
};

// ── Abrir y cerrar ───────────────────────────────────────────────────────────────────────────────

// Se REDEFINE en cada apertura a propósito: `game.osd.html()` deja el html que pinte en la definición
// de la pantalla, así que sin esto, volver a abrir la pausa después de INVITAR enseñaría el enlace de
// la vez anterior en vez del menú.
M.abrir = function () {
  G.osd.define('pausa', { html: M.panel(), sitio: 'centro', escala: 0.8, boton: 18, ancho: 300 });
  G.osd.abrir('pausa');
  return true;
};

// ==SALIR-AL-EDITOR== v2
// El Mundo se abre de dos maneras y SALIR no significa lo mismo en las dos: encima del editor es
// CERRAR la capa, y en una página sin editor detrás es irse del juego.
//
// ⚠️ v2 — «página propia» NO significa «sin editor detrás». `/map/<x>` sirve el MISMO `index.html`
// (server.py:1431): el editor está debajo, solo que tapado por la capa del Mundo. Mandar a `/` desde
// ahí PIERDE EL MAPA, porque `mcMapName()` (app.js:21476) lo saca de la URL y en `/` no hay ninguno:
// al pulsar el icono «mundo» se entraba en `default` en vez de volver a `empty3`. Cerrando la capa,
// la URL se queda en `/map/<x>` y el viaje de vuelta funciona solo.
M.hayEditorDetras = function () {
  try {
    if (typeof closeWorld !== 'function') return false;            // motor sin capa de Mundo
    var q = location.search || '';
    if (/[?&](osd|intro)=1/.test(q)) return false;                 // escaparate/intro: no hay editor que enseñar
    var capa = document.getElementById('mc-modal');
    if (!capa || capa.hidden) return false;
    if (!document.getElementById('tabs')) return false;            // la barra del editor, lo que queda debajo
    // El editor es superficie de desarrollo: quien no tenga el permiso no debe aterrizar en él.
    // `sesion-guardia` ya sabe quién eres; si no está (modo desarrollo), no hay nada que esconder.
    var g = G.guardia;
    if (g && g.permisos && g.permisos.length && !g.puede('snippet.editar_sistema')) return false;
    return true;
  } catch (e) { return false; }
};
M.enElEditor = M.hayEditorDetras;   // el nombre viejo sigue valiendo (lo usan las pruebas)

// El rótulo dice a dónde lleva. Se puede cambiar sin miedo porque la identidad del botón es su
// `data-osd`, no su texto (lo pone `M.boton`) — al revés que en los botones de `game.osd` a pelo.
M.textoSalir = function () { return M.hayEditorDetras() ? 'IR AL EDITOR' : 'SALIR'; };

M.salir = function () {
  if (!M.hayEditorDetras()) { location.href = '/'; return true; }
  // Cerrar la pantalla ANTES que el Mundo: al revés queda la capa OSD encima del editor, sin nada
  // debajo que la cierre.
  try { G.osd.cerrar(); } catch (e) {}
  closeWorld();     // ⛔ sin `location.href`: la URL /map/<x> ES lo que hace posible la vuelta
  return true;
};
// ==FIN-SALIR-AL-EDITOR==

M.continuar = function () {
  G.osd.cerrar();
  // ⚠️ La captura del puntero va DENTRO del manejador del clic: es un gesto de usuario, y pedida
  // tras un `await` o un `rAF` el navegador la rechaza y el jugador vuelve sin poder mirar. Y va
  // DESPUÉS de cerrar, porque `mcLockPointer` no recaptura mientras hay pantalla abierta.
  try { if (typeof mcLockPointer === 'function') mcLockPointer(); } catch (e) {}
  return true;
};

// ── Lo que hacen los botones ─────────────────────────────────────────────────────────────────────

// El enlace lo firma el servidor (`POST /api/invitaciones`), nunca el navegador: un vale que se
// pudiera fabricar aquí no valdría para nada, porque lo que lo hace valer es la firma con el secreto
// que solo tiene el servidor.
// ⛔ AQUÍ ESTÁ (c). Invitar era firmar un enlace y quedarse fuera: el invitado entraba en
// multijugador (lo arranca `invitacion-multi` al ver el `?invita=`) y el anfitrión seguía a solas en
// su propio mapa, mandando gente a una fiesta a la que él no iba. Ahora el MISMO vale que se firma
// para el enlace me mete a mí, que es lo que pidió el dueño: «lo lógico es que ambos estén».
//
// Encender va sin `await` y con `.catch()`: que el árbitro esté caído no puede impedir que se enseñe
// el enlace, que es lo que el jugador vino a buscar y sigue siendo válido.
M.invitar = function () {
  return M.pideVale().then(function (r) {
    if (!r.ok) return G.osd.html(M.panelInvita(null, null, M.porQueNo(r.codigo, r.d)));
    if (r.d.vale) M.guardaVale(r.d.vale);
    G.osd.html(M.panelInvita(r.d.enlace, r.d.escritura));
    // Y el anfitrión dentro. Se repinta al acabar porque la nota dice si estoy o no, y cuando esto
    // termina ya no dice lo mismo que cuando se pintó.
    if (r.d.vale && !M.multiPuesto()) {
      Promise.resolve(M.enciende())
        .then(function () { if (M.enPantalla('INVITAR')) G.osd.html(M.panelInvita(r.d.enlace, r.d.escritura)); })
        .catch(function (e) { console.warn('👥 menu-juego: invité pero no pude entrar yo:', e && e.message); });
    }
  }).catch(function (e) {
    G.osd.html(M.panelInvita(null, null, 'No se ha podido hablar con el servidor: ' + e.message));
  });
};

// 401 y 403 no son el mismo problema y no se arreglan igual: uno se arregla entrando y el otro no se
// arregla (no es tu mapa). Decir «error» a las dos cosas manda a la gente al sitio equivocado.
M.porQueNo = function (codigo, d) {
  if (codigo === 401) return 'Entra con tu cuenta para poder invitar.';
  if (codigo === 403) return 'Este mapa no es tuyo, así que no puedes repartir acceso.';
  return (d && d.error) || 'No se ha podido crear el enlace.';
};

// Cuatro pasos y vuelta a empezar: un menú de consola no tiene deslizadores, tiene un botón que gira.
// El valor vive en `game.mouseSpeed`, que ya persiste por su cuenta.
// ⚠️ El primer paso es 0,25 porque ESE es el de fábrica (`mc.sens=0.000625` sobre una base de 0,0025,
// `app.js:7709`), no 1. Con una lista que empezara en 0,5 no habría forma de volver a la sensibilidad
// con la que se entró, que es la que casi todo el mundo va a querer.
M.PASOS_RATON = [0.25, 0.5, 1, 2];

M.giraRaton = function () {
  const i = M.PASOS_RATON.indexOf(G.mouseSpeed);
  G.mouseSpeed = M.PASOS_RATON[(i + 1) % M.PASOS_RATON.length];
  return G.mouseSpeed;
};

// ── Las acciones ─────────────────────────────────────────────────────────────────────────────────
//
// Una acción se escribe con CERO parámetros y se la llama sin argumentos; el 3.er argumento de
// `alPulsar` no cambia cómo corre el botón, solo DECLARA qué usa de este snippet para que
// `game.osd.entorno()` lo sirva y `game.osd.dump()` sepa imprimir una receta que corra copiada a F12.
// Sin él el botón funciona igual, pero el volcado lo marca en `falta`.
//
// ⚠️ Y por eso además son de UNA LÍNEA, con el trabajo de verdad en un `M.loquesea` de arriba: el
// volcado corta el código de la acción a las 18 líneas (`MC_OSD_MAX_LINEAS`, `app.js:19935`) y le pega
// un «… (N líneas más)» que luego relee como si fueran nombres de variable — una acción larga sale en
// `dump()` con un `falta: ['l','neas','m','s']` que no significa nada y esconde los avisos que sí.

M.instalaAcciones = function () {
  const yo = { M, G };   // lo que TODAS las acciones de aquí usan; se declara una vez
  G.osd.alPulsar(M.CLAVE + 'continuar', function () { M.continuar(); }, yo);
  G.osd.alPulsar(M.CLAVE + 'multi', function () { G.osd.html(M.panelMulti()); }, yo);
  G.osd.alPulsar(M.CLAVE + 'multi-onoff', function () { M.conmutaMulti(); }, yo);
  G.osd.alPulsar(M.CLAVE + 'volver-multi', function () { G.osd.html(M.panelMulti()); }, yo);
  G.osd.alPulsar(M.CLAVE + 'invitar', function () { M.invitar(); }, yo);
  G.osd.alPulsar(M.CLAVE + 'ajustes', function () { G.osd.html(M.panelAjustes()); }, yo);
  G.osd.alPulsar(M.CLAVE + 'volver', function () { G.osd.html(M.panel()); }, yo);
  G.osd.alPulsar(M.CLAVE + 'volar', function () { G.volar(); G.osd.html(M.panelAjustes()); }, yo);
  G.osd.alPulsar(M.CLAVE + 'raton', function () { M.giraRaton(); G.osd.html(M.panelAjustes()); }, yo);
  G.osd.alPulsar(M.CLAVE + 'pantalla', function () { try { G.pantallaCompleta(); } catch (e) {} }, yo);
  G.osd.alPulsar(M.CLAVE + 'mundos', function () { location.href = '/map'; }, yo);
  // SALIR va a la portada, que en modo público es `web/menu.html`. Aquí SÍ se navega —y es la única
  // acción que lo hace a propósito— porque salir del juego es irse a otra página; lo que no puede
  // navegar es CONTINUAR, que es volver a la partida que ya está cargada.
  G.osd.alPulsar(M.CLAVE + 'salir', function () { M.salir(); }, yo);
  return true;
};

// ── El enganche de Esc ───────────────────────────────────────────────────────────────────────────

// Lo que ya se encarga `app.js` de cerrar, escalón por escalón. Si algo de esto está abierto, la
// tecla SE DEJA PASAR: cerrarlo es suyo, y adelantarnos sería reimplementar la escalera.
M.TAPADO = ['#mas-menu', '#snip-modal', '#ag-modal', '#mc-note', '#mc-picker'];

M.hayAlgoEncima = function () {
  try {
    if (mc && mc.notePlacing) return true;
    for (const sel of M.TAPADO) {
      const n = document.querySelector(sel);
      if (n && !n.hidden) return true;
    }
  } catch (e) {}
  return false;
};

M.off = function () {
  if (M._mano) window.removeEventListener('keydown', M._mano, true);
  M._mano = null;
  return true;
};

M.on = function () {
  M.off();                                     // reejecutar el snippet no puede apilar dos oyentes
  M.instalaAcciones();
  M._mano = function (e) {
    if (e.key !== 'Escape') return;
    try {
      const modal = document.querySelector('#mc-modal');
      if (!modal || modal.hidden) return;      // no estamos en el Mundo: Esc no es nuestro
      if (!mc || !mc.active) return;
      if (mc.osdAbierta) return;               // ya hay pantalla: que `app.js` la cierre (el 2.º paso)
      if (M.hayAlgoEncima()) return;           // hay algo encima: su escalón manda
    } catch (err) { return; }                  // ante la duda, NO se secuestra la tecla
    e.preventDefault();
    e.stopImmediatePropagation();
    M.abrir();
  };
  window.addEventListener('keydown', M._mano, true);
  return true;
};

M.estado = function () {
  return { version: M.VERSION, puesto: !!M._mano, mapa: M.mapa(), abierta: G.osd && G.osd.abierta };
};

M.on();
